using System;using System.Drawing;using System.Windows.Forms;
class DialogStyleChecks{[STAThread]static void Main(){Application.EnableVisualStyles();using(var f=new PixelFrame{Text="开启字幕确认",Size=new Size(620,330)}){var body=new RetroLabel{Text="开启中文字幕后，本节全部对话的最高评价将从3星降为1星。\n是否仍要开启？",BackColor=GameTheme.Navy,Dock=DockStyle.Fill,Padding=new Padding(20),Font=GameTheme.Body(13)};f.Controls.Add(body);f.Show();Application.DoEvents();if(body.BackColor!=Color.FromArgb(25,53,55)||f.Region==null||f.Region.IsVisible(0,0))throw new Exception("Dialog styling mismatch");using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,f.ClientRectangle);b.Save("dialog-green-frame.png");}f.Close();}Console.WriteLine("PASS: green body, clipped outer corners, shared dialog frame.");}}
